/* Independent exact-arithmetic reference for printf("%g", (double)float) precision 6.
   Uses exact decimal big-integer expansion of the f32: value = m * 2^e.
   If e>=0: digits = m*2^e, scale s=0.   If e<0: digits = m*5^(-e), scale s=e.
   value = DIGITS * 10^s exactly.  No f64 formatting used anywhere. */
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <stdint.h>

typedef struct { int n; unsigned char d[512]; } Big; /* d[0] = least significant digit */

static void big_from_u32(Big *b, uint32_t v) {
    b->n = 0;
    if (v == 0) { b->d[0] = 0; b->n = 1; return; }
    while (v) { b->d[b->n++] = (unsigned char)(v % 10); v /= 10; }
}
static void big_mul_small(Big *b, unsigned m) {
    unsigned carry = 0;
    for (int i = 0; i < b->n; i++) { unsigned t = (unsigned)b->d[i] * m + carry; b->d[i] = (unsigned char)(t % 10); carry = t / 10; }
    while (carry) { b->d[b->n++] = (unsigned char)(carry % 10); carry /= 10; }
}

/* Format f32 bits exactly as glibc %g with precision 6. */
void fmt_g6(uint32_t bits, char *out) {
    int neg = (bits >> 31) & 1;
    uint32_t be = (bits >> 23) & 0xFF;
    uint32_t frac = bits & 0x7FFFFF;
    char *p = out;

    if (be == 0xFF) {
        if (frac) { strcpy(out, neg ? "-nan" : "nan"); }
        else      { strcpy(out, neg ? "-inf" : "inf"); }
        return;
    }
    if (neg) *p++ = '-';
    if (be == 0 && frac == 0) { *p++ = '0'; *p = 0; return; }

    uint32_t m; int e;
    if (be == 0) { m = frac;              e = -149; }        /* subnormal */
    else         { m = frac | 0x800000;   e = (int)be - 150; } /* normal: 2^(be-127) * m/2^23 */

    Big B; big_from_u32(&B, m);
    int s;
    if (e >= 0) { for (int i = 0; i < e; i++) big_mul_small(&B, 2); s = 0; }
    else        { for (int i = 0; i < -e; i++) big_mul_small(&B, 5); s = e; }

    int L = B.n;
    int X = L - 1 + s;              /* decimal exponent before rounding */
    int R;                          /* 6 significant digits, 100000..999999 */
    if (L <= 6) {
        R = 0;
        for (int i = L - 1; i >= 0; i--) R = R * 10 + B.d[i];
        for (int i = L; i < 6; i++) R *= 10;
    } else {
        R = 0;
        for (int i = 0; i < 6; i++) R = R * 10 + B.d[L - 1 - i];
        int h = B.d[L - 7];                                 /* half digit */
        int more = 0;
        for (int i = 0; i < L - 7; i++) if (B.d[i]) { more = 1; break; }
        /* FE_TONEAREST: round_away = half_bit && (last_digit_odd || more_bits) */
        if (h > 5 || (h == 5 && (more || (R & 1)))) R++;
        if (R == 1000000) { R = 100000; X++; }              /* exponent bump */
    }

    char dig[8];
    snprintf(dig, sizeof dig, "%06d", R);

    if (X < -4 || X >= 6) {                                  /* %e style */
        int last = 5; while (last > 0 && dig[last] == '0') last--;
        *p++ = dig[0];
        if (last >= 1) { *p++ = '.'; for (int i = 1; i <= last; i++) *p++ = dig[i]; }
        *p++ = 'e'; *p++ = (X < 0) ? '-' : '+';
        int ax = X < 0 ? -X : X;
        p += sprintf(p, "%02d", ax);
        *p = 0;
    } else {                                                 /* %f style, X in [-4,5] */
        int last = 5; while (last > 0 && dig[last] == '0') last--;
        if (X >= 0) {
            for (int i = 0; i <= X; i++) *p++ = dig[i];
            if (last > X) { *p++ = '.'; for (int i = X + 1; i <= last; i++) *p++ = dig[i]; }
        } else {
            *p++ = '0'; *p++ = '.';
            for (int i = 0; i < -X - 1; i++) *p++ = '0';
            for (int i = 0; i <= last; i++) *p++ = dig[i];
        }
        *p = 0;
    }
}

int main(int argc, char **argv) {
    if (argc > 1 && strcmp(argv[1], "--sweep") == 0) {
        /* exhaustive-ish sweep comparing against glibc printf in-process */
        long long bad = 0, n = 0;
        uint64_t step = (argc > 2) ? strtoull(argv[2], 0, 0) : 1021;
        for (uint64_t b = 0; b <= 0xFFFFFFFFull; b += step) {
            uint32_t bits = (uint32_t)b;
            float f; memcpy(&f, &bits, 4);
            char mine[64], theirs[64];
            fmt_g6(bits, mine);
            snprintf(theirs, sizeof theirs, "%g", (double)f);
            n++;
            if (strcmp(mine, theirs) != 0) {
                if (bad < 40) printf("MISMATCH bits=%08x mine=[%s] glibc=[%s]\n", bits, mine, theirs);
                bad++;
            }
        }
        printf("sweep step=%llu checked=%lld mismatches=%lld\n", (unsigned long long)step, n, bad);
        return bad != 0;
    }
    /* each arg: a float literal (strtof) OR 0xBITS32 if prefixed with 'b:' */
    for (int i = 1; i < argc; i++) {
        uint32_t bits;
        if (strncmp(argv[i], "b:", 2) == 0) bits = (uint32_t)strtoul(argv[i] + 2, 0, 16);
        else { float f = strtof(argv[i], 0); memcpy(&bits, &f, 4); }
        float f; memcpy(&f, &bits, 4);
        char mine[64], theirs[64];
        fmt_g6(bits, mine);
        snprintf(theirs, sizeof theirs, "%g", (double)f);
        printf("%s\tbits=%08x\tmine=%s\tglibc=%s\t%s\n", argv[i], bits, mine, theirs,
               strcmp(mine, theirs) ? "**MISMATCH**" : "ok");
    }
    return 0;
}

/* Batch differential driver: feeds float input strings through the oracle binary
   (identity oracle: ./test7_executable A B C 0 0 0  =>  "fmt(A) fmt(B) fmt(C)")
   and compares each field against the independent reference fmt_g6.        */
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <stdint.h>

void fmt_g6(uint32_t bits, char *out);

#define ORACLE "/workspace/dataset/test7_executable"

static int total = 0, bad = 0;

static void run_triple(char *a[3]) {
    char cmd[1024], got[256];
    snprintf(cmd, sizeof cmd, "%s '%s' '%s' '%s' 0 0 0 2>&1", ORACLE, a[0], a[1], a[2]);
    FILE *fp = popen(cmd, "r");
    if (!fp || !fgets(got, sizeof got, fp)) { printf("RUNFAIL %s\n", cmd); if (fp) pclose(fp); bad++; return; }
    pclose(fp);
    got[strcspn(got, "\n")] = 0;

    char want[256]; want[0] = 0;
    for (int i = 0; i < 3; i++) {
        uint32_t bits; float f = strtof(a[i], 0); memcpy(&bits, &f, 4);
        if (bits == 0x80000000u) bits = 0;   /* identity oracle: -0.0 + 0.0 == +0.0 */
        char one[64]; fmt_g6(bits, one);
        if (i) strcat(want, " ");
        strcat(want, one);
    }
    total++;
    if (strcmp(want, got) != 0) { bad++; printf("MISMATCH args=[%s %s %s] want=[%s] oracle=[%s]\n", a[0],a[1],a[2],want,got); }
    else printf("ok  %-22s %-22s %-22s -> %s\n", a[0], a[1], a[2], got);
}

int main(int argc, char **argv) {
    char *buf[3]; int k = 0;
    char line[256];
    while (fgets(line, sizeof line, stdin)) {
        line[strcspn(line, "\r\n")] = 0;
        if (!line[0] || line[0] == '#') continue;
        buf[k++] = strdup(line);
        if (k == 3) { run_triple(buf); for (int i=0;i<3;i++) free(buf[i]); k = 0; }
    }
    while (k < 3 && k > 0) { buf[k++] = strdup("0"); }
    if (k == 3) { run_triple(buf); }
    fprintf(stderr, "\n=== triples=%d mismatches=%d ===\n", total, bad);
    return bad != 0;
}

/* Scan f32 space for GENUINE ties at 6 significant digits, and for
   near-ties whose exact binary expansion continues past the tie digit. */
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <stdint.h>

typedef struct { int n; unsigned char d[512]; } Big;
static void big_from_u32(Big *b, uint32_t v){ b->n=0; if(!v){b->d[0]=0;b->n=1;return;} while(v){b->d[b->n++]=v%10;v/=10;} }
static void big_mul_small(Big *b, unsigned m){ unsigned c=0; for(int i=0;i<b->n;i++){unsigned t=b->d[i]*m+c;b->d[i]=t%10;c=t/10;} while(c){b->d[b->n++]=c%10;c/=10;} }

/* returns: 0 = no rounding needed (L<=6), 1 = genuine tie, 2 = h==5 but more_bits (near-tie above),
            3 = other. Fills X, q(6 digits), and digit string. */
static int classify(uint32_t bits, int *Xout, int *qout, int *hout, int *moreout, int *Lout, char *digs) {
    uint32_t be=(bits>>23)&0xFF, frac=bits&0x7FFFFF;
    if (be==0xFF) return -1;
    if (be==0&&frac==0) return -1;
    uint32_t m; int e;
    if (be==0){m=frac;e=-149;} else {m=frac|0x800000;e=(int)be-150;}
    Big B; big_from_u32(&B,m); int s;
    if(e>=0){for(int i=0;i<e;i++)big_mul_small(&B,2);s=0;} else {for(int i=0;i<-e;i++)big_mul_small(&B,5);s=e;}
    int L=B.n; *Lout=L; *Xout=L-1+s;
    if (digs) { for(int i=0;i<L&&i<80;i++) digs[i]='0'+B.d[L-1-i]; digs[L<80?L:80]=0; }
    if (L<=6){ *qout=-1;*hout=-1;*moreout=0; return 0; }
    int q=0; for(int i=0;i<6;i++) q=q*10+B.d[L-1-i];
    int h=B.d[L-7]; int more=0; for(int i=0;i<L-7;i++) if(B.d[i]){more=1;break;}
    *qout=q;*hout=h;*moreout=more;
    if(h==5&&!more) return 1;
    if(h==5&&more)  return 2;
    return 3;
}

int main(int argc,char**argv){
    const char*mode = argc>1?argv[1]:"ties";
    if(!strcmp(mode,"ties")){
        /* find genuine ties, print a spread */
        long long cnt=0; int shown=0;
        uint64_t lo = argc>2?strtoull(argv[2],0,0):0x30000000ull;
        uint64_t hi = argc>3?strtoull(argv[3],0,0):0x50000000ull;
        uint64_t step = argc>4?strtoull(argv[4],0,0):1;
        for(uint64_t b=lo;b<hi;b+=step){
            uint32_t bits=(uint32_t)b; int X,q,h,more,L; char digs[96];
            int c=classify(bits,&X,&q,&h,&more,&L,digs);
            if(c==1){ cnt++;
                if(cnt%1==0 && shown<200000){ float f; memcpy(&f,&bits,4);
                    printf("TIE bits=%08x exact=%s L=%d X=%d q=%d qpar=%s val=%.17g fmt=%g\n",
                        bits,digs,L,X,q,(q&1)?"ODD":"EVEN",(double)f,(double)f); shown++; }
            }
        }
        fprintf(stderr,"genuine ties found in range: %lld\n",cnt);
        return 0;
    }
    /* explain mode: args are float strings */
    for(int i=2;i<argc;i++){
        float f=strtof(argv[i],0); uint32_t bits; memcpy(&bits,&f,4);
        int X,q,h,more,L; char digs[96];
        int c=classify(bits,&X,&q,&h,&more,&L,digs);
        printf("%-18s bits=%08x class=%d L=%d X=%d exactdigits=%s  q=%d(%s) h=%d more=%d  glibc%%g=%g\n",
            argv[i],bits,c,L,X,digs,q,(q&1)?"odd":"even",h,more,(double)f);
    }
    return 0;
}

/* Catalog: for each decimal exponent X, find genuine ties (q even and q odd),
   preferring floats with a SHORT exact decimal literal (so test vectors are readable). */
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <stdint.h>

typedef struct { int n; unsigned char d[512]; } Big;
static void big_from_u32(Big *b, uint32_t v){ b->n=0; if(!v){b->d[0]=0;b->n=1;return;} while(v){b->d[b->n++]=v%10;v/=10;} }
static void big_mul_small(Big *b, unsigned m){ unsigned c=0; for(int i=0;i<b->n;i++){unsigned t=b->d[i]*m+c;b->d[i]=t%10;c=t/10;} while(c){b->d[b->n++]=c%10;c/=10;} }

/* exact decimal literal of the float, e.g. "983040.5" ; returns length */
static void exact_literal(uint32_t bits, char *out){
    uint32_t be=(bits>>23)&0xFF, frac=bits&0x7FFFFF; uint32_t m; int e;
    if(be==0){m=frac;e=-149;} else {m=frac|0x800000;e=(int)be-150;}
    Big B; big_from_u32(&B,m); int s;
    if(e>=0){for(int i=0;i<e;i++)big_mul_small(&B,2);s=0;} else {for(int i=0;i<-e;i++)big_mul_small(&B,5);s=e;}
    /* strip trailing zeros of the fractional part only (i.e. increase s) */
    while(s<0 && B.n>1 && B.d[0]==0){ for(int i=0;i<B.n-1;i++) B.d[i]=B.d[i+1]; B.n--; s++; }
    char *p=out; int L=B.n;
    if(s>=0){ for(int i=L-1;i>=0;i--)*p++='0'+B.d[i]; for(int i=0;i<s;i++)*p++='0'; }
    else {
        int ip = L + s; /* integer digits */
        if(ip<=0){ *p++='0'; *p++='.'; for(int i=0;i<-ip;i++)*p++='0'; for(int i=L-1;i>=0;i--)*p++='0'+B.d[i]; }
        else { for(int i=L-1;i>=L-ip;i--)*p++='0'+B.d[i]; *p++='.'; for(int i=L-ip-1;i>=0;i--)*p++='0'+B.d[i]; }
    }
    *p=0;
}
static int is_tie(uint32_t bits,int*Xo,int*qo){
    uint32_t be=(bits>>23)&0xFF, frac=bits&0x7FFFFF;
    if(be==0xFF||(be==0&&frac==0))return 0;
    uint32_t m;int e;
    if(be==0){m=frac;e=-149;}else{m=frac|0x800000;e=(int)be-150;}
    Big B;big_from_u32(&B,m);int s;
    if(e>=0){for(int i=0;i<e;i++)big_mul_small(&B,2);s=0;}else{for(int i=0;i<-e;i++)big_mul_small(&B,5);s=e;}
    int L=B.n; if(L<7)return 0; *Xo=L-1+s;
    if(B.d[L-7]!=5)return 0;
    for(int i=0;i<L-7;i++) if(B.d[i]) return 0;
    int q=0;for(int i=0;i<6;i++)q=q*10+B.d[L-1-i]; *qo=q;
    return 1;
}
#define NX 100
static char bestE[NX][80], bestO[NX][80];   /* per X+50: even-q and odd-q winners */
static int lenE[NX], lenO[NX];

int main(void){
    for(int i=0;i<NX;i++){lenE[i]=lenO[i]=9999;}
    for(uint64_t b=0;b<0x7F800000ull;b++){
        uint32_t bits=(uint32_t)b; int X,q;
        if(!is_tie(bits,&X,&q)) continue;
        int idx=X+50; if(idx<0||idx>=NX) continue;
        char lit[200]; exact_literal(bits,lit); int l=(int)strlen(lit);
        if(q&1){ if(l<lenO[idx]){lenO[idx]=l;strcpy(bestO[idx],lit);} }
        else    { if(l<lenE[idx]){lenE[idx]=l;strcpy(bestE[idx],lit);} }
    }
    for(int i=0;i<NX;i++){
        int X=i-50;
        if(lenE[i]<9999||lenO[i]<9999){
            printf("X=%-4d evenq=%-24s oddq=%-24s\n", X,
                lenE[i]<9999?bestE[i]:"-", lenO[i]<9999?bestO[i]:"-");
        }
    }
    return 0;
}
